#import "SLAuthStore.h"
#import <Security/Security.h>
@implementation SLAuthStore
+ (NSString *)readService:(NSString *)service fallback:(NSString *)key {NSDictionary *q=[NSDictionary dictionaryWithObjectsAndKeys:(id)kSecClassGenericPassword,(id)kSecClass,service,(id)kSecAttrService,(id)kCFBooleanTrue,(id)kSecReturnData,(id)kSecMatchLimitOne,(id)kSecMatchLimit,nil];CFTypeRef out=NULL;OSStatus status=SecItemCopyMatching((CFDictionaryRef)q,&out);if(status==errSecSuccess&&out){NSData *d=[(NSData *)out autorelease];NSString *s=[[[NSString alloc]initWithData:d encoding:NSUTF8StringEncoding]autorelease];if([s length])return s;}return [[NSUserDefaults standardUserDefaults]stringForKey:key];}
+ (void)writeService:(NSString *)service token:(NSString *)raw fallback:(NSString *)key {NSString *token=[raw stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]];NSDictionary *base=[NSDictionary dictionaryWithObjectsAndKeys:(id)kSecClassGenericPassword,(id)kSecClass,service,(id)kSecAttrService,nil];SecItemDelete((CFDictionaryRef)base);[[NSUserDefaults standardUserDefaults]removeObjectForKey:key];if(![token length])return;NSMutableDictionary *add=[NSMutableDictionary dictionaryWithDictionary:base];[add setObject:[token dataUsingEncoding:NSUTF8StringEncoding] forKey:(id)kSecValueData];if(SecItemAdd((CFDictionaryRef)add,NULL)!=errSecSuccess)[[NSUserDefaults standardUserDefaults]setObject:token forKey:key];[[NSUserDefaults standardUserDefaults]synchronize];}
+ (NSString *)token{return [self readService:@"ru.slashlib.client.github" fallback:@"SLGitHubToken"];}
+ (void)setToken:(NSString *)token{[self writeService:@"ru.slashlib.client.github" token:token fallback:@"SLGitHubToken"];}
+ (NSString *)siteToken{return [self readService:@"ru.slashlib.client.site" fallback:@"SLAPIToken"];}
+ (void)setSiteToken:(NSString *)raw {NSString *t=[raw stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]];if([t hasPrefix:@"Bearer "]||[t hasPrefix:@"bearer "])t=[t substringFromIndex:7];[self writeService:@"ru.slashlib.client.site" token:t fallback:@"SLAPIToken"];}
@end
